orders = [(1, 40.0), (2, 150.0), (3, 75.0)]

# cursor FOR loop + IF inside: the classic data-driven flow
for order_id, total in orders:
    if total > 100:
        print(f'order {order_id}: VIP')
    else:
        print(f'order {order_id}: STANDARD')

customers = [(1, 200), (2, 600), (3, 1500), (4, 50)]

for cid, points in customers:
    if points >= 1000:
        tier = 'gold'
    elif points >= 500:
        tier = 'silver'
    else:
        tier = 'bronze'
    print(f'{cid}: {tier}')
